import json
import base64
import hashlib
import hmac
import os
import time
from urllib.parse import parse_qs

from fastapi import FastAPI, Depends, HTTPException, Request, status
from fastapi.security import OAuth2PasswordBearer
from fastapi.testclient import TestClient
from pydantic import BaseModel

SECRET_KEY = 'your-secret'
ALGORITHM = 'HS256'
oauth2_scheme = OAuth2PasswordBearer(tokenUrl='token')


class PasswordContext:
    """Salted PBKDF2 password hashing (stdlib only)."""

    def hash(self, password):
        salt = os.urandom(16)
        digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100_000)
        return salt.hex() + '$' + digest.hex()

    def verify(self, password, hashed):
        salt_hex, digest_hex = hashed.split('$')
        digest = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt_hex), 100_000)
        return hmac.compare_digest(digest.hex(), digest_hex)


class JWTError(Exception):
    pass


def _b64e(raw):
    return base64.urlsafe_b64encode(raw).rstrip(b'=').decode()


def _b64d(text):
    return base64.urlsafe_b64decode(text + '=' * (-len(text) % 4))


class jwt:
    @staticmethod
    def encode(payload, key, algorithm=ALGORITHM):
        header = {'alg': algorithm, 'typ': 'JWT'}
        data = dict(payload)
        if 'exp' in data:
            data['exp'] = int(data['exp'])
        signing = _b64e(json.dumps(header, separators=(',', ':')).encode()) + '.' + \
            _b64e(json.dumps(data, separators=(',', ':')).encode())
        sig = hmac.new(key.encode(), signing.encode(), hashlib.sha256).digest()
        return signing + '.' + _b64e(sig)

    @staticmethod
    def decode(token, key, algorithms=None):
        try:
            head, body, sig = token.split('.')
            expected = hmac.new(key.encode(), f'{head}.{body}'.encode(), hashlib.sha256).digest()
            if not hmac.compare_digest(expected, _b64d(sig)):
                raise JWTError('bad signature')
            payload = json.loads(_b64d(body))
        except JWTError:
            raise
        except Exception as exc:
            raise JWTError(str(exc))
        if 'exp' in payload and payload['exp'] < time.time():
            raise JWTError('expired')
        return payload


pwd_context = PasswordContext()
users_db = {}
app = FastAPI()


class UserRegister(BaseModel):
    username: str
    password: str
    email: str


@app.post('/register')
def register(user: UserRegister):
    if user.username in users_db:
        raise HTTPException(status_code=400, detail='Username taken')
    users_db[user.username] = {
        'username': user.username,
        'hashed_password': pwd_context.hash(user.password),
        'email': user.email
    }
    return {'message': f'User {user.username} created'}


@app.post('/token')
async def login(request: Request):
    form = parse_qs((await request.body()).decode())
    username = form.get('username', [''])[0]
    password = form.get('password', [''])[0]
    user = users_db.get(username)
    if not user or not pwd_context.verify(password, user['hashed_password']):
        raise HTTPException(status_code=401, detail='Bad credentials')
    token = jwt.encode({'sub': user['username'], 'exp': time.time() + 3600}, SECRET_KEY, algorithm=ALGORITHM)
    return {'access_token': token, 'token_type': 'bearer'}


@app.get('/profile')
def profile(token: str = Depends(oauth2_scheme)):
    credentials_error = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail='Invalid token',
        headers={'WWW-Authenticate': 'Bearer'},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except JWTError:
        raise credentials_error
    user = users_db.get(payload.get('sub'))
    if user is None:
        raise credentials_error
    return {'username': user['username'], 'email': user['email']}


client = TestClient(app)

r = client.post('/register', json={'username': 'pymaster', 'password': 'secret123', 'email': 'py@master.com'})
print('POST /register →', json.dumps(r.json()))

r = client.post('/token', data={'username': 'pymaster', 'password': 'secret123'})
body = r.json()
shown = dict(body, access_token=body['access_token'][:3] + '...')
print('POST /token →', json.dumps(shown))

r = client.get('/profile', headers={'Authorization': f"Bearer {body['access_token']}"})
print('GET /profile →', json.dumps(r.json()))

# unauthenticated / invalid requests must be rejected with 401
assert client.get('/profile').status_code == 401
assert client.get('/profile', headers={'Authorization': 'Bearer bad.token.value'}).status_code == 401
